const materialsRead = defineDatabasePermission((permission) =>
  permission
    .collection<KnowledgeMaterial>(KNOWLEDGE_MATERIALS_COLLECTION)
    .read([...KNOWLEDGE_MATERIAL_READ_FIELDS]),
);

const materialsEdit = defineDatabasePermission((permission) =>
  permission
    .collection<KnowledgeMaterial>(KNOWLEDGE_MATERIALS_COLLECTION)
    .read([...KNOWLEDGE_MATERIAL_READ_FIELDS])
    .create([...KNOWLEDGE_MATERIAL_CREATE_FIELDS])
    .update([...KNOWLEDGE_MATERIAL_UPDATE_FIELDS]),
);

/**
 * Reading a material and editing one, both bounded by which records the operation reaches.
 *
 * `view` is the read-only operation the colleague and the assistant use. `edit` adds creation and update, and is
 * granted only to the supervisor set. Their `materials` data scope is what the seed fills with a record selection:
 * all records for the supervisor, two named ones for the colleague.
 */
export const knowledgeMaterialsResource = defineCompositeResource(
  KNOWLEDGE_MATERIALS_RESOURCE,
  (resource) =>
    resource
      .title({ key: 'knowledge.resource.title', ns: 'nb3-factory' })
      .action('view', (action) =>
        action
          .title({ key: 'knowledge.action.view', ns: 'nb3-factory' })
          .grant(KNOWLEDGE_MATERIALS_SCOPE, materialsRead, {
            title: { key: 'knowledge.scope.materials', ns: 'nb3-factory' },
          }),
      )
      .action('edit', (action) =>
        action
          .title({ key: 'knowledge.action.edit', ns: 'nb3-factory' })
          .grant(KNOWLEDGE_MATERIALS_SCOPE, materialsEdit, {
            title: { key: 'knowledge.scope.materials', ns: 'nb3-factory' },
          }),
      ),
);

/** The reference the seed and the providers use to build and register grants. */
export function knowledgeMaterialsReference() {
  return knowledgeMaterialsResource.reference();
}

/** The record selection that reaches every material. */
export function allMaterials() {
  return selection.all();
}

/** The record selection that reaches exactly the given material identifiers. */
export function materialsById(ids: readonly string[]) {
  return selection.records(ids);
}

import { defineTools } from '@nocobase/ai-employee';
import { z } from 'zod';

import { knowledgeServiceToken } from '../../knowledge/service.js';

/**
 * The assistant's only tool: read the materials the person asking may read.
 *
 * It is deliberately the only way an answer can reach material text. The tool asks the same service the materials
 * page reads through, and that service applies the stored permission-set grants with `withPolicy`, so a material the
 * asker may not open cannot be retrieved here either. The assistant therefore has no path to a supervisor-only
 * material that the page does not also have, and nothing in the tool needs to know which materials those are.
 *
 * The tool only reads. It is `SPECIFIED`, so it exists for the employee that names it, and `ALLOW`, so a read does
 * not raise an approval prompt on every question.
 */
export default defineTools({
  scope: 'SPECIFIED',
  execution: 'backend',
  defaultPermission: 'ALLOW',
  i18n: { namespace: 'nb3-factory' },
  introduction: {
    title: 'Read knowledge materials',
    about:
      'List the materials this person may read, or one of them by identifier.',
  },
  definition: {
    name: 'read-knowledge-materials',
    description:
      'Read the knowledge materials available to the current user. Call it before answering any question about the materials. Without an argument it returns every material the user may read; pass an identifier to read one.',
    schema: z.object({
      id: z
        .string()
        .optional()
        .describe('The identifier of a single material to read.'),
    }),
  },
  dependencies: { knowledge: knowledgeServiceToken },
  invoke: async (ctx, args) => {
    const { id } = (args ?? {}) as { id?: string };
    const actorId = String(ctx.actor.id);
    const materials = id
      ? [await ctx.deps.knowledge.visibleMaterial(actorId, id)].filter(
          (material) => material !== undefined,
        )
      : await ctx.deps.knowledge.visibleMaterials(actorId);
    return {
      status: 'success',
      content: {
        // Said explicitly so a model cannot read an empty list as a lookup failure and answer from memory instead.
        materials,
        total: materials.length,
      },
    };
  },
});

