      product: z.string(),
      quantity: z.number().int().positive(),
      notes: z.string().optional(),
    }),
  },
  dependencies: { orders: orderServiceToken },
  invoke: async (ctx, args) => {
    const order = await ctx.deps.orders.create(ctx.actor, args);
